    {"id": 2, "claim": "Uninsured individuals are responsible for paying the full cost of medical procedures out-of-pocket.", "evidence": "Definition of being uninsured in the context of healthcare costs; lack of third-party payer.", "weight": 0.15, "depends_on": [1]},
    {"id": 3, "claim": "Insured individuals typically have a portion of the cost covered by their insurance plan, significantly reducing their out-of-pocket expense.", "evidence": "Function of health insurance coverage (copays, coinsurance, deductibles are generally lower than full price).", "weight": 0.15, "depends_on": [1]},
    {"id": 4, "claim": "Higher out-of-pocket costs create a stronger financial barrier to seeking care.", "evidence": "Economic principle of price elasticity and access to care; health economics literature on cost-sharing.", "weight": 0.15, "depends_on": [2, 3]},
    {"id": 5, "claim": "A stronger financial barrier leads to a higher probability of declining a non-emergency medical procedure.", "evidence": "Behavioral response to cost constraints; studies show inverse relationship between price and utilization of elective/non-urgent procedures.", "weight": 0.15, "depends_on": [4]},
    {"id": 6, "claim": "In emergency or life-threatening situations, patients are far less likely to decline necessary diagnostic imaging regardless of insurance status or cost.", "evidence": "Emergency department data indicating near-universal acceptance of indicated emergent imaging due to the immediate threat to life.", "weight": 0.15, "depends_on": []},
    {"id": 7, "claim": "The majority of CT scans ordered in clinical practice are for non-emergent diagnostic clarification rather than acute emergencies, meaning cost is a relevant decision factor for most patients.", "evidence": "Healthcare utilization reports showing many CT orders are for diagnostic clarification rather than acute emergencies; this validates the applicability of the cost-barrier argument to the general population.", "weight": 0.25, "depends_on": [5, 6]}
